import json

lower=[2,2,0,0,0,0,0,0,0]
upper=[4,4,4,4,4,4,4,4,4]
degrees=list(range(4,37))
hdegrees=[1,2,3,4]
n=len(lower)

def bounded_partitions(total):
    out=[]
    def rec(i,prev,rem,a):
        if i==n:
            if rem==0: out.append(a[:])
            return
        lo=lower[i]; hi=min(upper[i],prev,rem)
        for x in range(hi,lo-1,-1):
            rec(i+1,x,rem-x,a+[x])
    rec(0,upper[0],total,[])
    return out

def pieri(mu,lam):
    # mu/lambda is a horizontal strip iff mu_i >= lambda_i >= mu_{i+1}.
    return all(mu[i]>=lam[i] and lam[i] >= (mu[i+1] if i+1<n else 0) for i in range(n))

def eye(m): return [[1 if i==j else 0 for j in range(m)] for i in range(m)]
def matmul(A,B):
    return [[sum(A[i][k]*B[k][j] for k in range(len(B))) for j in range(len(B[0]))] for i in range(len(A))]
def det_bareiss(A):
    m=len(A)
    if m==0:return 1
    B=[r[:] for r in A]; sign=1; prev=1
    for k in range(m-1):
        if B[k][k]==0:
            z=next((i for i in range(k+1,m) if B[i][k]),None)
            if z is None:return 0
            B[k],B[z]=B[z],B[k];sign=-sign
        p=B[k][k]
        for i in range(k+1,m):
            for j in range(k+1,m): B[i][j]=(B[i][j]*p-B[i][k]*B[k][j])//prev
        prev=p
        for i in range(k+1,m): B[i][k]=0
    return sign*B[-1][-1]

def smith_witness(M):
    A=[r[:] for r in M]; r=len(A); c=len(A[0]) if r else 0
    U=eye(r); V=eye(c); ops=[]
    def rs(i,j):
        A[i],A[j]=A[j],A[i]; U[i],U[j]=U[j],U[i]; ops.append(['rs',i,j])
    def cs(i,j):
        for X in (A,V):
            for row in X: row[i],row[j]=row[j],row[i]
        ops.append(['cs',i,j])
    def ra(i,j,q):
        A[i]=[x+q*y for x,y in zip(A[i],A[j])]
        U[i]=[x+q*y for x,y in zip(U[i],U[j])]
        ops.append(['ra',i,j,q])
    def ca(i,j,q):
        for X in (A,V):
            for row in X: row[i]+=q*row[j]
        ops.append(['ca',i,j,q])
    def rn(i):
        A[i]=[-x for x in A[i]]; U[i]=[-x for x in U[i]]; ops.append(['rn',i])
    k=0
    while k<r and k<c:
        candidates=[(abs(A[i][j]),i,j) for i in range(k,r) for j in range(k,c) if A[i][j]]
        if not candidates: break
        _,i,j=min(candidates)
        if i!=k:rs(i,k)
        if j!=k:cs(j,k)
        while True:
            # Euclidean clearing of pivot column and row.
            progressed=True
            while progressed:
                progressed=False
                for i in range(k+1,r):
                    if A[i][k]:
                        q=A[i][k]//A[k][k]
                        ra(i,k,-q)
                        if A[i][k]: rs(i,k)
                        progressed=True; break
                if progressed: continue
                for j in range(k+1,c):
                    if A[k][j]:
                        q=A[k][j]//A[k][k]
                        ca(j,k,-q)
                        if A[k][j]: cs(j,k)
                        progressed=True; break
            bad=None
            p=A[k][k]
            for i in range(k+1,r):
                for j in range(k+1,c):
                    if A[i][j] % p:
                        bad=(i,j);break
                if bad:break
            if bad is None: break
            # Inject a nondivisible residual entry into pivot row, then repeat gcd reduction.
            ra(k,bad[0],1)
        if A[k][k]<0: rn(k)
        k+=1
    D=A
    diag=[D[i][i] for i in range(min(r,c)) if D[i][i]!=0]
    # Exact independent replay and identity checks.
    R=[row[:] for row in M]
    for op in ops:
        typ,i,j,*z=op
        if typ=='rs': R[i],R[j]=R[j],R[i]
        elif typ=='cs':
            for row in R: row[i],row[j]=row[j],row[i]
        elif typ=='ra': R[i]=[x+z[0]*y for x,y in zip(R[i],R[j])]
        elif typ=='ca':
            for row in R: row[i]+=z[0]*row[j]
        else: R[i]=[-x for x in R[i]]
    UMV=matmul(matmul(U,M),V) if r and c else ([[] for _ in range(r)] if c==0 else [])
    return {'operationLog':ops,'replay':R,'U':U,'V':V,'D':D,'smithDiagonal':diag,'rank':len(diag),
            'checks':{'replayEqualsD':R==D,'UMVEqualsD':UMV==D,'diagonal':all(D[i][j]==0 for i in range(r) for j in range(c) if i!=j),'positiveDivisible':all(x>0 for x in diag) and all(diag[i+1]%diag[i]==0 for i in range(len(diag)-1)),'detU':det_bareiss(U),'detV':det_bareiss(V)}}

records=[]
for d in degrees:
    cols=bounded_partitions(d)
    labels=[]; rows=[]; zeros=[]
    for h in hdegrees:
        if d-h<sum(lower): continue
        for lam in bounded_partitions(d-h):
            row=[1 if pieri(mu,lam) else 0 for mu in cols]
            if any(row): labels.append([h,lam]); rows.append(row)
            else: zeros.append([h,lam])
    # Include zero Pieri rows in the actual complete presentation matrix.
    all_labels=labels+zeros
    M=rows+[[0]*len(cols) for _ in zeros]
    w=smith_witness(M)
    tors=[x for x in w['smithDiagonal'] if x>1]
    records.append({'degree':d,'orderedBasis':cols,'rowLabels':all_labels,'nonzeroRowCount':len(labels),'zeroRowLabels':zeros,'M':M,'matrixShape':[len(M),len(cols)],**w,'quotientFreeRank':len(cols)-w['rank'],'torsionInvariantFactors':tors})
summary=[]
for x in records:
    summary.append({'degree':x['degree'],'shape':x['matrixShape'],'rank':x['rank'],'smithDiagonal':x['smithDiagonal'],'quotientFreeRank':x['quotientFreeRank'],'torsionInvariantFactors':x['torsionInvariantFactors'],'zeroRowCount':len(x['zeroRowLabels']),'allChecks':all(x['checks'].values())})
print(json.dumps({'inputs':{'lower':lower,'upper':upper,'degrees':degrees,'hDegrees':hdegrees,'columnOrder':'reverse lexicographic','rowOrder':'h-degree increasing, then source reverse lexicographic; zero rows appended after nonzero rows to retain complete matrix'},'degreeSummaries':summary,'records':records},separators=(',',':')))
